package com.lynn.s34598901.medtrack.data.medications

import androidx.room.Entity
import androidx.room.ForeignKey
import androidx.room.Index
import androidx.room.PrimaryKey
import com.lynn.s34598901.medtrack.data.patients.Patient

/**
 * Represents one medication record saved for a patient
 */
@Entity(tableName = "medications",
    foreignKeys = [ForeignKey(entity = Patient :: class, parentColumns = ["patientID"], childColumns = ["patientID"], onDelete = ForeignKey.CASCADE)], indices = [Index(
        "patientID"
    )])
data class Medication(

    // Unique medication record ID generated by Room
    @PrimaryKey(autoGenerate = true)
    val medicationId: Int = 0,

    // Patient ID
    val patientID: String,

    // Name of the medication
    val name: String,

    // Dosage amount and unit
    val dosage: String,

    // Frequency of the medication should be taken
    val frequency: String,

    // TIme when the medication should be taken
    val time: String,

    // Type of medication
    val type: String,

    // Optional notes entered by the patient
    val notes: String,

    // Check whether the medication has been marked as taken
    val isTaken: Boolean = false,

    // Stores the date when the medication was marked as taken
    val dateTaken: String = ""
)
